route('/auth/reauthenticate','post','reauthenticate',AUTH,'Confirm current password for sensitive actions',role='student, faculty or admin (self only)',body='Reauthentication',data=ref('ReauthenticationResult'),desc='Bound to current server session; no transferable credential returned. Freshness window is a configuration value. Wrong password 401, failed attempts 429. Required before admin faculty creation, approval/publication/status changes, configuration updates and private verification-document retrieval. A failed check never extends freshness.')
route('/auth/password','put','changeOwnPassword',AUTH,'Change own password',role='student, faculty or admin (self only)',body='PasswordChange',desc='Verify current password, enforce new-password policy and difference from current password. Admin and super_admin accounts also send the email code from POST /auth/password/requests (challengeId and otp); a missing, wrong or expired code is 422. Atomically update hash, clear activation flag, revoke all sessions including caller and clear cookies. Login required again. Audit password change.',cookies=True)
route('/auth/password/requests','post','requestPasswordChangeCode',AUTH,'Send a code to your own email before changing your password',role='student, faculty or admin (self only)',data=ref('Challenge'),code=202,desc='Sends a six-digit code to the signed-in account email; no email is accepted in the request. A new request replaces the previous code; asking again inside the resend cooldown returns 429. Only accounts that must confirm a password change by email can ask (admin and super_admin; every role when PASSWORD_CHANGE_OTP_ROLES=all); others get 422. The code is for PUT /auth/password only and cannot be used for password recovery. No OTP in response.')
route('/auth/recovery/requests','post','requestPasswordRecovery',AUTH,'Send email recovery OTP',body='RecoveryStart',data=ref('Challenge'),code=202,desc='Uniform 202 and decoy challenge for unknown/wrong-portal/inactive account. Same configurable expiry, resend and aggregate attempt limits as verification. Only email. Repeated requests invalidate prior recovery challenge and any unconsumed reset grant; no password change yet.')
route('/auth/recovery/verify','post','verifyRecoveryOtp',AUTH,'Exchange recovery OTP for one-time reset credential',body='OtpRequest',data=ref('ResetGrant'),desc='422 for invalid, expired or consumed OTP; 429 on attempt exhaustion. Atomic consumption. Reset credential hash stored with user and purpose; proposed five-minute lifetime. Cache-Control: no-store; never put credential in a URL or logs.')
route('/auth/recovery/reset','post','resetPassword',AUTH,'Consume reset credential and set password',body='PasswordReset',desc='422 for expired, unknown or consumed reset credential or unchanged password. One successful reset per credential, including concurrent requests. Atomically set password, clear activation requirement and revoke every session plus recovery/verification credentials. No automatic login. Email verification remains a separate step. Audit PASSWORD_RESET.',cookies=True)
route('/auth/sessions','get','listOwnSessions',AUTH,'List own session families',role='student, faculty or admin (self only)',data=array(ref('Session')),paginated=True,desc='No raw refresh/access token or fingerprint returned. jti is a stable opaque session-family identifier; rotation does not change this management ID.')
route('/admin/me/profile','put','updateOwnAdminProfile',AUTH,'Update own admin profile',role='admin (self only)',body='AdminProfileUpdate',data=ref('User'),desc='Full replacement of the three editable fields; the account is always the authenticated one, never a client-supplied ID. Email is read-only here: changing it needs email verification (LMS-99). Audit profile.updated with before and after values of these fields only.')
