FAC='Faculty'
route('/admin/faculty','post','createFaculty',FAC,'Admin provision faculty identity and draft profile',role='admin; faculty.create',body='FacultyCreate',data=ref('FacultyCreated'),code=201,desc='Recent reauthentication required. Unique normalized email; cannot promote existing student or create admin here. Assign faculty role atomically; pending, unpublished by default. Queue email activation/recovery challenge, never send or return a password. Faculty sets password via recovery and verifies email before login. Inactive identities cannot authenticate. Admin-only onboarding remains provisional pending client sign-off.')
roster_filters=[query('search',string(100),'Name or email contains, case-insensitive.'),query('categoryId',uuid,'Tutors with an active assignment in this category or below it; hides invitations. Unknown id 422.')]
route('/admin/faculty','get','listFacultyAdmin',FAC,'List tutors and outstanding invitations',role='admin; faculty.read',data=array(ref('FacultyListItem')),paginated=True,params=[query('status',dict(enum('all','pending','verified','published','suspended'),default='all'),'Tab: pending = invited + pending; all also includes rejected and expired.'),*roster_filters,query('sort',dict(enum('recent','oldest','name'),default='recent'),'recent/oldest by appliedAt, then id; name by full name or email.')],desc='Admin Faculty screen (LMS-78). One row per faculty profile or PENDING invitation; accepted and revoked invitations are not listed. Cache-Control: no-store.')
route('/admin/faculty/status-counts','get','getFacultyStatusCounts',FAC,'Count tutors per Faculty screen tab',role='admin; faculty.read',data=ref('FacultyStatusCounts'),params=roster_filters,desc='Badge counts for the tabs, narrowed by the same search and categoryId as the list.')
op=route('/admin/faculty/invitations','post','inviteFaculty',FAC,'Invite tutors by email',role='admin; faculty.create',body='FacultyInvite',data=ref('FacultyInviteResult'),code=201,desc='LMS-79. All or nothing: an address with any account or an unexpired pending invitation makes the whole request 409 FACULTY_INVITE_CONFLICT with one message per address in errors.emails; expired invitations are expired first so the address can be invited again. One pending invitation per email is enforced by a partial unique index. Token: 32 random bytes, base64url, single use, SHA-256 hash stored, lifetime FACULTY_INVITE_TTL_HOURS. Emails are sent through the configured provider after commit; an undeliverable invitation is revoked (delivered=false), and 502 EMAIL_DELIVERY_FAILED is returned when none could be sent. Rate-limited per admin (429 with Retry-After). Every invitation and delivery failure is audited without the token.')
op['responses']['502']={'description':'EMAIL_DELIVERY_FAILED: no invitation email could be sent; the invitations were revoked so they can be sent again.','content':{'application/json':{'schema':ref('ErrorResponse')}}}
route('/admin/faculty/{facultyId}','get','getFacultyAdmin',FAC,'Read a tutor application for the verification drawer',role='admin; faculty.read',data=ref('FacultyDetail'),desc='Screen 27b. Screening answers, documents with verification state, the subjects chosen at onboarding with their current tutor price, and the pricing/consent state. Cache-Control: no-store.')
route('/admin/faculty/{facultyId}/profile','put','setFacultyProfileAdmin',FAC,'Replace faculty qualifications and experience',role='admin; faculty.update',body='FacultyProfileWrite',data=ref('FacultyProfile'),desc='Arrays replace existing records atomically. Experience endDate must not precede startDate; null means ongoing. Any material profile edit after approval resets review to pending and unpublishes atomically; existing terms receipt retained.')
route('/faculty/me','get','getOwnFacultyProfile',FAC,'Read own faculty profile and eligibility',role='faculty (self only)',data=ref('FacultyProfile'),desc='Allowed before terms acceptance; id derived from identity. Never accepts arbitrary owner ID.')
route('/faculty/me/profile','put','setOwnFacultyProfile',FAC,'Replace own qualifications and experience',role='faculty (self only); faculty.update_self',body='FacultyProfileWrite',data=ref('FacultyProfile'),desc='Current terms acceptance and password activation required. Same review reset and date validation as admin edits. Cannot set approval, roles, active status, subjects or publication.')
route('/faculty/terms','get','getFacultyTerms',FAC,'Read current effective faculty terms',role='faculty or admin',data=ref('Terms'),desc='Allowed before acceptance. Immutable approved content/version delivered as text, not executable HTML. 503 until approved current version is configured.',decision='Client must supply and approve immutable terms content, version, and reacceptance policy. No placeholder terms are legally effective.')
route('/faculty/me/terms-acceptance','post','acceptFacultyTerms',FAC,'Record own acceptance of current terms',role='faculty (self only)',body='TermsAcceptance',data=ref('TermsReceipt'),desc='Server records UTC timestamp; no backdating or admin acceptance for another user. Same version repeated is idempotent; stale version 409. Password activation must be complete; allowed before approval.',decision='Approved content/version and effect of later terms changes on existing approval/publication.')
route('/admin/faculty/{facultyId}/review','put','reviewFaculty',FAC,'Approve ("Verify & publish") or reject a tutor application',role='admin; faculty.approve',body='FacultyReview',data=ref('FacultyDetail'),desc='Screen 27b, LMS-39. Only pending applications (409 INVALID_TRANSITION). Approve verifies the remaining documents, records the approver and sets isPublished to publish; reject needs a reason and unpublishes. expectedRevision must match (409 STALE_REVISION). The tutor is emailed. Approval alone does not allow sign-in: every subject needs a tutor price (GET /admin/prices/awaiting).')
route('/admin/faculty/{facultyId}/documents/{documentId}/verification','put','setFacultyDocumentVerification',FAC,'Mark a verification document as verified',role='admin; faculty.approve',body='DocumentVerification',data=ref('FacultyDetail'),desc='Screen 27b "Mark as verified". Audited.')
route('/admin/faculty/{facultyId}/publication','put','setFacultyPublication',FAC,'Publish or withdraw faculty profile',role='admin; faculty.publish',body='PublicationWrite',data=ref('FacultyProfile'),desc='Recent reauthentication required. Publishing requires approval, current terms, verified email, active account/profile and at least one active catalogue assignment. Otherwise 409. Withdrawal immediate. expectedRevision prevents stale updates. Never publishes documents.')
route('/admin/faculty/{facultyId}/status','put','setFacultyActiveStatus',FAC,'Activate or deactivate faculty',role='admin; faculty.update',body='ActiveWrite',data=ref('FacultyProfile'),desc='Recent reauthentication required. Deactivate identity and profile, revoke all sessions, unpublish atomically. Reactivation preserves approval/terms but requires explicit republishing. Eligibility checked live, without relying on JWT claims. Audit reason.')
for base, role, suffix in [('/admin/faculty/{facultyId}/documents','admin; faculty.documents','Admin'),('/faculty/me/documents','faculty (self only)','Self')]:
    route(base,'get','listFacultyDocuments'+suffix,FAC,'List verification document metadata',role=role,data=array(ref('PrivateDocument')),paginated=True,desc='Private metadata only; no storage keys or public URLs. Own metadata readable during onboarding.')
    if suffix=='Admin':
        route(base,'post','uploadFacultyDocument',FAC,'Upload private faculty verification document',role=role,body='DocumentUpload',data=ref('PrivateDocument'),code=202,multipart=True,desc='Recent reauthentication required. Single file, maximum 10 MiB. Proposed PDF/JPEG/PNG allowlist with extension, declared type and magic-byte agreement. Quarantine and malware scan; pending is not accessible. Replacement/new evidence after approval resets review and unpublishes. Stream only through authorized endpoint. Document retrieval audited.')
    route(base+'/{documentId}/file','get','getFacultyDocumentFile'+suffix,FAC,'Retrieve private clean verification file',role=role,desc='Recent reauthentication required. Owner linkage verified in database; 404 for inaccessible ownership. Pending/rejected scan state 409. No public storage URL; bytes streamed with private,no-store, nosniff and safe Content-Disposition attachment. Admin and owning faculty only.')
    P[base+'/{documentId}/file']['get']['responses']['200']={'description':'Authorized file bytes, always as an attachment, with a sandbox CSP. X-Document-Previewable: true for PDF and images. No malware scanner exists yet (PENDING_DECISIONS F4), so pending files are served to admins.','headers':{'Content-Disposition':{'schema':{'type':'string'}},'Cache-Control':{'schema':{'type':'string','enum':['private, no-store']}}},'content':{m:{'schema':{'type':'string','format':'binary'}} for m in ['application/pdf','image/jpeg','image/png','application/msword','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.presentationml.presentation']}}
    P[base+'/{documentId}/file']['get']['responses']['409']={'$ref':'#/components/responses/E409'}
route('/faculty','get','listPublishedFaculty',FAC,'List eligible published faculty projections',data=array(ref('FacultyPublic')),paginated=True,desc='Minimal public publication-verification listing only; no discovery filters. Shared live eligibility predicate excludes unapproved, inactive, unverified, unpublished, terms-incomplete or unassigned faculty. Return no email, documents, review reasons or identity status.')
route('/faculty/{facultyId}','get','getPublishedFaculty',FAC,'Read eligible public faculty projection',data=ref('FacultyPublic'),desc='Same predicate as public list; 404 when ineligible. This is not a booking authorization result.')
ONB='Faculty onboarding'
route('/faculty/onboarding/session','post','startFacultyOnboarding',ONB,'Check a faculty invitation link',body='OnboardingSessionRequest',data=ref('OnboardingSession'),desc='Screen 43b. Every unusable link (unknown, used, revoked, expired) returns the same 422 INVITATION_INVALID. Rate-limited per IP.')
route('/faculty/onboarding/catalogue','get','getFacultyOnboardingCatalogue',ONB,'Category tree and offerings for the subject picker',data=ref('OfferingTree'),desc='Screen 43c column picker: visible categories that lead to a leaf, and one offering per leaf: its category curriculum, with subject = the leaf itself (id and name) and board and level null. Picking a leaf adds a card; the card is the curriculumId.')
route('/faculty/onboarding/applications','post','submitFacultyApplication',ONB,'Submit a faculty application',body='FacultyApplication',data=ref('FacultyApplicationResult'),code=201,multipart=True,desc='Screens 43b-43d. One transaction consumes the invitation and creates the user (faculty role, email verified by the link), the profile, one assignment per subject card and the three documents (Photo ID, degree certificate, PAN card). 409 ALREADY_REGISTERED; 422 field errors, DOCUMENT_INVALID or INVITATION_INVALID. The tutor cannot sign in until approved (27b) and every subject is priced (29). Rate-limited per IP.')
route('/faculty/me/price-consent','get','getFacultyPriceConsent',FAC,'Read own session prices awaiting acceptance',role='faculty (self only); faculty.read_self',data=ref('PriceConsent'),desc='After the first sign-in (login returns requiresTermsAcceptance=true). 403 FACULTY_PENDING_PRICING until approved and fully priced.')
route('/faculty/me/price-consent','post','decideFacultyPriceConsent',FAC,'Accept or decline own session prices',role='faculty (self only); faculty.update_self',body='PriceConsentDecision',data=ref('PriceConsent'),desc='For the exact prices shown (snapshotHash); 409 PRICES_CHANGED otherwise. Declining keeps the portal blocked and emails the approving admin; a later price change asks again. The consent screen design is not final.')

CONSENT='Consent'
pdf_response=lambda desc:{'description':desc,'headers':{'Content-Disposition':{'schema':{'type':'string'}},'Cache-Control':{'schema':{'type':'string'}}},'content':{'application/pdf':{'schema':{'type':'string','format':'binary'}}}}
route('/regions/countries','get','listCountries','Regions','List the countries the platform serves',data=array(ref('Country'),20),desc='Public. Active countries in display order with their dialling code and default time zone, for the mobile number country picker and to pick the policies for a country. Cache-Control: public, max-age 300.')
route('/policies/current','get','listCurrentPolicies',CONSENT,'List current legal policy versions',params=[query('country',string(2,minLength=2,pattern='^[A-Z]{2}$'),'Country of the student, derived by the client from the dialling code of the mobile number (GET /regions/countries). Required: a country never receives another country\'s texts.',required=True)],data=array(ref('Policy'),4),desc='Terms of Use, Privacy Policy, Child Safety Policy and Student Terms for the country, one current version each. Drives the step 4 links and the signing modal header ("Student Terms v1.0 · Effective 1 September 2026"). 503 until the client-supplied texts are configured for that country; an unsupported country is 422.',decision='Policy texts and the Student Terms PDF are supplied by the client (SOW A1.8). The Terms of Use summary in the UI hard-codes the 20-minute billable rule; it must match the configured setting and the supplied text.')
op=route('/policies/{policyId}/file','get','getPolicyFile',CONSENT,'Download a policy PDF',desc='Blank PDF for the modal preview and "View full document" (consent doc GET /consent/pdf/). Content-Disposition inline; public cache allowed per version.')
op['responses']['200']=pdf_response('Policy PDF bytes.')
route('/consent/guardian-signatures','post','signGuardianConsent',CONSENT,'Sign the Student Terms as parent or guardian',body='GuardianSignatureUpload',data=ref('GuardianConsentReceipt'),code=201,multipart=True,desc='Opened from the date-of-birth popup when the server-computed age is under 18, before the account exists (consent doc POST /consent/sign/). Server overlays the signature, "Parent/guardian of <studentFullName>", UTC timestamp and client IP on the last page, flattens, stores a new object per signing and records its SHA-256. Client IP comes from the trusted proxy configuration, never the first X-Forwarded-For entry. 422 when the date of birth is 18 or over, the policy is not the current Student Terms, or the mode and fields disagree. Strict per-IP rate limit. Unlinked consents expire after a configured period and are purged with their PDFs. Re-signing after the consent is linked to an account returns 409. The signature is a recorded acknowledgement, not a cryptographic or identity-verified signature.',decision='Project plan R4 (guardian identity not verified) accepted on 2026-10-29; the written acceptance is still to be filed. Deliberate differences from the consent signing document: the PDF shows "Parent/guardian of <student>" instead of a signer name, because the modal collects only the signature (the guardian name from step 3 is stored at registration); and the client IP comes from the trusted proxy configuration rather than the first X-Forwarded-For entry, which a client can forge. Separate consent documents per country (India, UAE) are pending; see docs/PENDING_DECISIONS.md.')
op=route('/consent/guardian-signatures/file','get','getPendingGuardianConsentFile',CONSENT,'Download the signed consent before registration',params=[{'name':'x-consent-token','in':'header','required':True,'description':'consentToken from the signing response. Header, never a URL.','schema':string(512)}],desc='Only the holder of an unexpired, unlinked consent token. 404 for unknown, expired or linked tokens. Cache-Control: private, no-store; Content-Disposition attachment (consent doc GET /consent/download/).')
op['responses']['200']=pdf_response('Signed consent PDF bytes.')
op=route('/students/me/guardian-consent/file','get','getOwnGuardianConsentFile',CONSENT,'Download own signed consent',role='student (self only)',desc='Linked consent of the authenticated student. 404 when none. Cache-Control: private, no-store.')
op['responses']['200']=pdf_response('Signed consent PDF bytes.')
route('/admin/students/{studentId}/guardian-consent','get','getStudentGuardianConsentAdmin',CONSENT,'Show a student signed consent record',role='admin; student.read',data=ref('GuardianConsentSummary'),desc='Metadata of the signed guardian consent of an under-18 student (studentId is the student profile id): Student Terms version and country, signing time, guardian name and relationship, and the SHA-256 of the signed PDF. The PDF is a separate download. 404 when the student has no consent. Cache-Control: private, no-store.')
route('/admin/students','get','listStudentsAdmin',CONSENT,'List students with their consent status',role='admin; student.read',data=array(ref('AdminStudent')),paginated=True,params=[query('q',string(100),'Part of the name, email or mobile number.'),query('country',string(2,minLength=2,pattern='^[A-Z]{2}$'),'Only students of this country.'),query('minor',{'type':'boolean'},'true: only students below their country\'s consent age; false: only the others.'),query('consent',enum('signed','missing','not_required'),'Only students with this consent status.')],desc='Newest first. A student is a minor when their age is below the guardian consent age of their country (read from the country table). The guardian contact and the consent status are shown against every minor; the signed PDF and its record are fetched per student (see the guardian-consent routes). Cache-Control: private, no-store.')
route('/admin/students/{studentId}','get','getStudentAdmin',CONSENT,'Show one student',role='admin; student.read',data=ref('AdminStudentDetail'),desc='The student, the learning profile chosen at registration (names only), the guardian contact and, for a minor with a signed consent, the consent record. studentId is the student profile id. 404 for an unknown student. Cache-Control: private, no-store.')
route('/admin/policies','get','listPoliciesAdmin',CONSENT,'List every policy version',role='admin; policy.read',data=array(ref('AdminPolicy'),500),params=[query('country',string(2,minLength=2,pattern='^[A-Z]{2}$'),'Only this country.'),query('type',enum('terms_of_use','privacy_policy','child_safety_policy','student_terms'),'Only this policy type.')],desc='All uploaded versions, newest first, current and past, for the Legal documents screen. Each can be opened with GET /policies/{policyId}/file.')
route('/admin/policies/coverage','get','getPolicyCoverageAdmin',CONSENT,'Which countries lack current policies',role='admin; policy.read',data=array(ref('PolicyCoverage'),20),desc='For every active country, the policy types that have no current version. Students of a country with a missing type cannot register (GET /policies/current answers 503), so the admin shows a warning until this is empty.')
route('/admin/policies','post','uploadPolicyAdmin',CONSENT,'Upload a policy version',role='admin; policy.create',body='PolicyUpload',data=ref('AdminPolicy'),code=201,multipart=True,desc='Recent reauthentication required. Stores the PDF and makes it the current version for its type and country in one transaction; the previous version stays on record because acceptances and consents point at it. 409 when that version already exists for the type and country, 422 for a file that is not a readable PDF or an unsupported country. Audited.')
route('/admin/policies/{policyId}/current','put','setPolicyCurrentAdmin',CONSENT,'Make an earlier policy version current again',role='admin; policy.update',data=ref('AdminPolicy'),desc='Recent reauthentication required. Switches which version is current for its type and country (to roll back a wrong upload). Audited.')
op=route('/admin/students/{studentId}/guardian-consent/file','get','getStudentGuardianConsentFileAdmin',CONSENT,'Download a student signed consent',role='admin; student.read',desc='Recent reauthentication required. Audited. Cache-Control: private, no-store.')
op['responses']['200']=pdf_response('Signed consent PDF bytes.')

CAT='Catalogue'
for plural, singular in [('categories','Category'),('boards','Board'),('subjects','Subject'),('levels','Level'),('curricula','Curriculum'),('teaching-languages','TeachingLanguage')]:
    desc='Admin-managed persistent catalogue. Unique code for named entities; archive with isActive=false instead of deleting referenced rows. '
    if singular=='Category': desc+='Seed four categories: School, University, JEE/NEET, Research & Skill Learning (combined). No category split required. '
    if singular=='TeachingLanguage': desc+='Onboarding step 2 "Preferred teaching language" options such as English & Hindi; final list supplied by Amentorz. '
    if singular=='Board': desc+='Seed NCERT and ICSE; State Board structures need named state-board entries decided by admin. NCERT is retained as requested business label pending terminology review. '
    if singular=='Curriculum': desc+='Created and kept in sync by the catalogue tree: each LEVEL leaf owns one curriculum, active only while the leaf and every ancestor are PUBLISHED (ADR 0003). A combination appears once in the tree. Unique categoryId+boardId+subjectId+levelId, treating null board as equal. Board required only for School; otherwise must be null. All references active. This tuple is the configured offering; alternate curricula for the same tuple need a reviewed contract change. '
    route('/catalogue/'+plural,'get','list'+singular+'s',CAT,'List active '+plural,data=array(ref(singular)),paginated=True,desc='Public projection excludes inactive or parent-inactive rows. '+desc,params=[query('categoryId',uuid),query('boardId',uuid),query('levelId',uuid,'Onboarding step 2 subjects: filter by category, board and level, then join subjectId with /catalogue/subjects.')] if singular=='Curriculum' else [query('categoryId',uuid,'Only levels scoped to this category.')] if singular=='Level' else None)
    route('/admin/catalogue/'+plural,'get','list'+singular+'sAdmin',CAT,'List all configured '+plural,role='admin; catalogue.read',data=array(ref(singular)),paginated=True,params=[query('isActive',boolean)],desc=desc)
    if singular=='Curriculum': continue  # curricula are created through the catalogue tree (ADR 0003)
    deferred = None if singular=='TeachingLanguage' else 'D12: admin create/edit of master lists is deferred; Sprint 1 seeds them and exposes list-only endpoints.'
    route('/admin/catalogue/'+plural,'post','create'+singular,CAT,'Create '+singular.lower(),role='admin; catalogue.manage',body=singular+'Write',data=ref(singular),code=201,desc=desc+'Audit create. Invalid relationships 422; duplicate 409.',decision=deferred)
    route('/admin/catalogue/'+plural+'/{id}','put','replace'+singular,CAT,'Replace or archive '+singular.lower(),role='admin; catalogue.manage',body=singular+'Write',data=ref(singular),desc=desc+'Audit old/new allowlisted values. Archival immediately removes affected assignments/prices from consumer resolution. Reject structural reparenting of referenced curricula with 409; archive and create new tuple instead.',decision=deferred)
tree_desc='Categories & Content tree (ADR 0003): CATEGORY > SUBSECTION > BOARD > SUBJECT > LEVEL; SUBSECTION and BOARD may be skipped; BOARD only where the category requires a board. Each LEVEL leaf owns one curriculum. '
route('/catalogue/tree','get','getCatalogueTree',CAT,'Published catalogue tree for one category',data=ref('TreeNode'),params=[query('categoryId',uuid,'Category id.',required=True)],desc=tree_desc+'Only nodes that are published and whose every ancestor is published. Unknown or inactive category 404. Cache-Control: public, max-age=60.')
route('/catalogue/nodes/{nodeId}','get','getCatalogueNode',CAT,'Published catalogue node with its path',data=ref('NodeDetail'),desc=tree_desc+'Draft, archived or hidden nodes 404.')
route('/admin/catalogue/tree','get','getCatalogueTreeAdmin',CAT,'Full catalogue tree with drafts and counts',role='admin; catalogue.read',data=ref('TreeNode'),params=[query('categoryId',uuid,'Category id.',required=True),query('q',string(100),'Name search; matches keep their ancestors and subtree.')],desc=tree_desc+'Includes DRAFT and ARCHIVED nodes, child counts and descendant counts by type (screen 28).')
route('/admin/catalogue/nodes/{nodeId}','get','getCatalogueNodeAdmin',CAT,'Catalogue node detail panel',role='admin; catalogue.read',data=ref('NodeDetail'),desc=tree_desc+'Counts whose source module does not exist yet are null, never estimated.')
route('/admin/catalogue/paths','post','createCataloguePath',CAT,'Add a whole path ending in a level',role='admin; catalogue.manage',body='PathWrite',data=ref('PathCreated'),code=201,desc=tree_desc+'Screen 28a. One transaction reuses existing board and subject nodes under the chosen parent and creates the missing ones, then the leaf and its curriculum. Existing path 409; the same combination under another subsection 409 (known limitation pending D11). Inactive or unknown references, a level of another category, or a board rule violation 422. New nodes start as DRAFT unless status is given. Audit each created node.')
route('/admin/catalogue/nodes','post','createCatalogueNode',CAT,'Create one catalogue node',role='admin; catalogue.manage',body='NodeCreate',data=ref('NodeDetail'),code=201,desc=tree_desc+'CATEGORY nodes are fixed (D8). Wrong parent type, archived parent or invalid reference 422; duplicate sibling slug or master value 409. Audit create.')
route('/admin/catalogue/nodes/reorder','put','reorderCatalogueNodes',CAT,'Set the order of every child of a parent',role='admin; catalogue.manage',body='NodeReorder',data=obj({'parentId':uuid,'orderedIds':array(uuid,500)}, ['parentId','orderedIds']),desc=tree_desc+'orderedIds must list every child exactly once, otherwise 422. Audit old and new order.')
route('/admin/catalogue/nodes/{nodeId}','put','updateCatalogueNode',CAT,'Edit a catalogue node',role='admin; catalogue.manage',body='NodeUpdate',data=ref('NodeDetail'),desc=tree_desc+'Changes name, slug, order, DRAFT/PUBLISHED status or the category booking flag. Setting a status on an archived node restores it; its parent must not be archived. Curricula below follow the published state. Audit old/new values.')
route('/admin/catalogue/nodes/{nodeId}/move','put','moveCatalogueNode',CAT,'Move a node under another parent',role='admin; catalogue.manage',body='NodeMove',data=ref('NodeDetail'),desc=tree_desc+'Same category only. Cycle, wrong parent type or archived parent 422. 409 while any curriculum in the subtree is used by students, tutors or library items (D16), or when the new parent already has a matching child. Curricula follow the new path. Audit old/new parent.')
route('/admin/catalogue/nodes/{nodeId}/archive','put','archiveCatalogueNode',CAT,'Archive a catalogue node',role='admin; catalogue.manage',data=ref('NodeDetail'),desc=tree_desc+'Soft archive only. Blocked with 409 while a child is not archived (D3). Category tabs cannot be archived (422). The leaf curriculum becomes inactive. Audit.')
route('/admin/faculty/{facultyId}/assignments','get','listFacultyAssignments',CAT,'List faculty catalogue assignments',role='admin; faculty.read',data=array(ref('Assignment')),paginated=True)
route('/admin/faculty/{facultyId}/assignments','post','createFacultyAssignment',CAT,'Assign faculty to configured curriculum tuple',role='admin; faculty.assign',body='AssignmentWrite',data=ref('Assignment'),code=201,desc='Unique faculty+curriculum including inactive assignments; reactivate existing row rather than duplicate. Active valid curriculum required. Assignment fixes category, board, subject and level together, avoiding contradictory independent assignments.')
route('/admin/faculty/{facultyId}/assignments/{assignmentId}','put','replaceFacultyAssignment',CAT,'Activate or deactivate faculty assignment',role='admin; faculty.assign',body='AssignmentWrite',data=ref('Assignment'),desc='404 if assignment belongs to another faculty. curriculumId is immutable after creation; mismatch 409. Deactivation may make faculty ineligible; price rules are kept and resolution of tutor-specific prices is unaffected (eligibility is checked by booking). Audit change.')
PRICE='Pricing'
price_rules='Rule per curriculum (category+board+subject+level offering) and optional tutor; facultyId null = default price. At most one active rule per curriculumId+facultyId (null treated as a value) for any overlapping effective window; overlap 409. gstPaise and studentPaysPaise are computed by the server on every create/update/bulk update and never accepted from clients. Integer paise >0; proposed safety maximum INR 1,000,000 requires review. Currency INR and duration 60 are fixed, not client input. No packages, bundles or credits. '
route('/admin/prices','get','listPriceRules',PRICE,'List price rules with GST and student totals',role='admin; pricing.read',data=array(ref('PriceRule')),paginated=True,params=[query('facultyId',uuid),query('defaultOnly',boolean,'true = only rules without a tutor.'),query('categoryId',uuid),query('boardId',uuid),query('subjectId',uuid),query('levelId',uuid),query('isActive',boolean),query('q',string(100),'Case-insensitive match on tutor, subject, board or level name.')],desc=price_rules)
route('/admin/prices/awaiting','get','listAwaitingTutorPrices',PRICE,'List approved tutors\' subjects that need a tutor price',role='admin; pricing.read',data=array(ref('AwaitingPrice'),5000),desc='Screen 29, LMS-40. One entry per subject card chosen at onboarding without an active tutor price; create it with POST /admin/prices (curriculumId and facultyId). A tutor can sign in once none of their entries remain.')
route('/admin/prices','post','createPriceRule',PRICE,'Create price rule',role='admin; pricing.manage',body='PriceRuleWrite',data=ref('PriceRule'),code=201,desc=price_rules+'Unknown curriculum, or unknown or inactive faculty profile, 422. Audit create.')
route('/admin/prices/bulk','put','bulkUpdatePriceRules',PRICE,'Save several price changes atomically',role='admin; pricing.manage',body='PriceBulkUpdate',data=array(ref('PriceRule'),200),desc=price_rules+'Screen 29b. changes edits existing rules; creates prices the "Not priced" subject cards listed in the same table (at least one entry, at most 200 in total). All or none: any stale revision, unknown id, overlap or unusable tutor returns 409 with errors keyed changes[i] or creates[i] and nothing is saved; an invalid body returns 422. GST and student totals recalculate on save. Audit each changed rule.')
route('/admin/prices/{priceId}','put','updatePriceRule',PRICE,'Update or deactivate price rule',role='admin; pricing.manage',body='PriceRuleUpdate',data=ref('PriceRule'),desc=price_rules+'curriculumId and facultyId are immutable. Stale expectedRevision 409. isActive=false deactivates. Audit old/new values.')
