code_s = string(50, pattern='^[a-z][a-z0-9_-]*$')
version_s = dict(integer(1), description='The version the change is based on (optimistic concurrency). A stale version returns 409 STALE_VERSION, unless the request is an idempotent retry whose values are already saved.')
